import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import { execSync } from "child_process";

const __dirname = path.dirname(fileURLToPath(import.meta.url));

const HOOK_MARKER_START = "# --- digit-i18n scope:";
const HOOK_FOOTER_MARKER = "# --- digit-i18n footer (always keep last) ---";

const HOOK_HEADER = `#!/usr/bin/env sh
# Auto-generated by "digit-i18n install-hooks" — do not hand-edit.
# Re-run the installer (from the relevant module folder) to add another
# module's scope, or to regenerate this file after an update.
# Warn-only: never blocks a commit. Runs lint + scan (report-only) and then
# export (writes/updates a local draft file — still never touches the
# backend, same as lint/scan). Nothing here ever calls "apply".
`;

// Confirmed by testing: \`set +e\` alone is NOT enough to guarantee a hook
// never blocks a commit — the shell's own exit status is whatever the LAST
// command returned, so a genuinely failing call still made git refuse the
// commit. This explicit footer, always kept as the literal last thing in
// the file, is what actually guarantees warn-only behavior.
const HOOK_FOOTER = `
${HOOK_FOOTER_MARKER}
exit 0
`;

export function findGitRoot(startDir) {
  let dir = startDir;
  while (true) {
    if (fs.existsSync(path.join(dir, ".git"))) return dir;
    const parent = path.dirname(dir);
    if (parent === dir) return null; // reached filesystem root without finding .git
    dir = parent;
  }
}

function escapeForShellDoubleQuotes(value) {
  return value.replace(/(["\\$`])/g, "\\$1");
}

// Confirmed by testing: git hooks run via a minimal, non-interactive shell
// that never sources .bashrc/.profile — so nvm-managed node, and PATH
// additions like yarn's global bin dir, are NOT set up the way they are in
// an interactive shell. Patching PATH inside the hook is fragile (depends on
// guessing exactly how each developer's machine is configured). Baking in
// the exact, already-resolved absolute paths — the node binary actually
// running this installer, and this package's own CLI entry script —
// sidesteps the whole problem instead of working around one symptom of it.
function buildScopeBlock(scopeRelPath) {
  const nodePath = escapeForShellDoubleQuotes(process.execPath);
  const cliEntryPath = escapeForShellDoubleQuotes(path.resolve(__dirname, "../../bin/digit-i18n.js"));

  return `
${HOOK_MARKER_START} ${scopeRelPath} ---
SCOPE="${scopeRelPath}"
STAGED=$(git diff --cached --name-only --diff-filter=ACM | grep "^$SCOPE/")
if [ -n "$STAGED" ]; then
  echo ""
  echo "digit-i18n: checking staged changes in $SCOPE ..."
  if [ -x "${nodePath}" ] && [ -f "${cliEntryPath}" ]; then
    (cd "$SCOPE" && "${nodePath}" "${cliEntryPath}" lint && "${nodePath}" "${cliEntryPath}" scan && "${nodePath}" "${cliEntryPath}" export)
  else
    echo "digit-i18n: the node/CLI path baked in at install time no longer exists — re-run 'digit-i18n install-hooks' from $SCOPE."
  fi
fi
`;
}

// Strips the footer (if present) so it can be re-appended fresh as the
// literal last thing in the file.
function stripFooter(content) {
  const idx = content.indexOf(HOOK_FOOTER_MARKER);
  return idx === -1 ? content : content.slice(0, idx);
}

function escapeForRegex(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

// Removes any existing block for this exact scope (whether from an older
// format or a stale absolute path) so re-running the installer always
// refreshes it, rather than silently keeping outdated content around.
function removeExistingScopeBlock(body, scopeRelPath) {
  const markerLine = `${HOOK_MARKER_START} ${scopeRelPath} ---`;
  const blockRegex = new RegExp(
    `\\n?${escapeForRegex(markerLine)}[\\s\\S]*?(?=\\n${escapeForRegex(HOOK_MARKER_START)}|$)`
  );
  return body.replace(blockRegex, "");
}

export function installHooksCommand({ cwd = process.cwd() } = {}) {
  const gitRoot = findGitRoot(cwd);

  if (!gitRoot) {
    console.error("Could not find a .git directory above the current folder — are you inside a git repo?");
    process.exitCode = 1;
    return;
  }

  const scopeRelPath = path.relative(gitRoot, cwd);
  if (!scopeRelPath || scopeRelPath.startsWith("..")) {
    console.error("Refusing to install a hook scoped to the git root itself — run this from inside a specific module folder.");
    process.exitCode = 1;
    return;
  }

  const hooksDir = path.join(gitRoot, ".githooks");
  const hookFile = path.join(hooksDir, "pre-commit");
  fs.mkdirSync(hooksDir, { recursive: true });

  let body = fs.existsSync(hookFile) ? stripFooter(fs.readFileSync(hookFile, "utf8")) : HOOK_HEADER;
  const hadScope = body.includes(`${HOOK_MARKER_START} ${scopeRelPath} ---`);
  body = removeExistingScopeBlock(body, scopeRelPath);
  body += buildScopeBlock(scopeRelPath);

  fs.writeFileSync(hookFile, body + HOOK_FOOTER);
  fs.chmodSync(hookFile, 0o755);

  console.log(
    hadScope
      ? `Refreshed the hook for "${scopeRelPath}" at ${hookFile} (using node: ${process.execPath})`
      : `Added "${scopeRelPath}" to the shared pre-commit hook at ${hookFile} (using node: ${process.execPath})`
  );

  execSync("git config core.hooksPath .githooks", { cwd: gitRoot });
  console.log(`Set git config core.hooksPath=.githooks for this clone (local config, not shared automatically).`);
  console.log(
    "\nThis hook is warn-only — it never blocks a commit. For staged changes under this module it runs lint, " +
      "scan, and export (export writes/updates a local draft file only — still no backend call). Other " +
      "developers need to run \"digit-i18n install-hooks\" themselves after pulling this (once, from inside this " +
      "same module) — it bakes in absolute paths to their own node/digit-i18n-cli install, and local git config " +
      "isn't shared by cloning/pulling alone."
  );
}
